<?php
namespace Tests\Feature;
use App\Models\{Lead,User};
use Illuminate\Foundation\Testing\RefreshDatabase;
use Tests\TestCase;
class LeadsPageTest extends TestCase { use RefreshDatabase;
 public function test_owner_can_view_paginated_leads(): void { $u=User::factory()->create(['email_verified_at'=>now()]); Lead::create(['user_id'=>$u->id,'name'=>'Empresa Demo']); $this->actingAs($u)->get('/leads')->assertOk()->assertSee('Empresa Demo'); }
 public function test_guest_is_redirected(): void { $this->get('/leads')->assertRedirect('/login'); }
 public function test_leads_are_isolated(): void { $a=User::factory()->create(['email_verified_at'=>now()]); $b=User::factory()->create(['email_verified_at'=>now()]); Lead::create(['user_id'=>$a->id,'name'=>'Privado A']); $this->actingAs($b)->get('/leads')->assertOk()->assertDontSee('Privado A'); }
 public function test_contact_links_and_extended_fields_are_rendered_for_owner(): void { $u=User::factory()->create(['email_verified_at'=>now()]); Lead::create(['user_id'=>$u->id,'name'=>'Empresa Social','phone'=>'(11) 99999-0000','instagram'=>'https://instagram.com/empresa']); $this->actingAs($u)->get('/leads')->assertOk()->assertSee('https://wa.me/5511999990000',false)->assertSee('https://instagram.com/empresa',false)->assertSee('Setor')->assertSee('Histórico de atividade'); }
 public function test_owner_can_update_profile_fields_and_activity_history(): void { $u=User::factory()->create(['email_verified_at'=>now()]); $lead=Lead::create(['user_id'=>$u->id,'name'=>'Empresa']); $this->actingAs($u)->put(route('leads.update',$lead),['name'=>'Empresa','sector'=>'Tecnologia','estimated_revenue'=>'120000.00','employee_count'=>12,'budget_value'=>'5000.00','instagram'=>'https://instagram.com/empresa','linkedin'=>'https://linkedin.com/company/empresa','tags_text'=>'B2B, Prioridade','responsible_user_id'=>$u->id,'note'=>'Primeiro contato realizado.'])->assertRedirect(); $lead->refresh(); $this->assertSame('Tecnologia',$lead->sector); $this->assertSame(['B2B','Prioridade'],$lead->tags); $this->assertSame($u->id,$lead->responsible_user_id); $this->assertDatabaseHas('lead_notes',['lead_id'=>$lead->id,'content'=>'Primeiro contato realizado.']); $this->assertDatabaseHas('lead_activities',['lead_id'=>$lead->id,'type'=>'tag']); $this->assertDatabaseHas('lead_activities',['lead_id'=>$lead->id,'type'=>'responsible']); }
 public function test_search_metrics_only_appear_on_search_results(): void { $u=User::factory()->create(['email_verified_at'=>now()]); $job=$u->prospectingJobs()->create(['keywords'=>['Dentista em São Paulo'],'search_parameters'=>['import_report'=>['total'=>4,'duplicates'=>2]],'status'=>'ok']); Lead::create(['user_id'=>$u->id,'prospecting_job_id'=>$job->id,'name'=>'Dentista A']); $this->actingAs($u)->get('/leads')->assertOk()->assertDontSee('Leads duplicados'); $this->actingAs($u)->get(route('leads.results',$job))->assertOk()->assertSee('Leads coletados')->assertSee('Leads duplicados')->assertSee('Leads sem site')->assertSee('WhatsApp validado'); }
}
